            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Calculate potential products
    prod_pos = max1 * max2  # Product of two largest positive numbers (or just top two)

    if min1 < 0 and min2 < 0:
        prod_neg = min1 * min2  # Product of two smallest negative numbers

        final_prod = prod_pos if prod_pos > prod_neg else prod_neg
    else:
        final_prod = prod_pos

    # Find the pair corresponding to the product
