        p2 = min1 * min2

    best_prod = max(p1, p2)

    if abs(best_prod - p1) < float('inf'):
        pair = (sorted_arr[-2], sorted_arr[-1])
    else:
        # Find the specific indices for min1 and min2 to return them as a tuple? 
